 "content": "def transform(grid):
    # The first 3x6 panel is the base. Fill its zero cells from the
    # following three color panels, resolving overlaps by 4 > 8 > 2.
    out = [row[:] for row in grid[:3]]
    priority = {2: 0, 8: 1, 4: 2}
    for r in range(3):
        for c in range(6):
            if out[r][c] == 0:
                colors = [grid[3 + panel * 3 + r][c] for panel in range(3)]
                colors = [color for color in colors if color in priority]
                if colors:
                    out[r][c] = max(colors, key=priority.get)
    return out

